def oku(y):
    with open(y, encoding="utf-8") as f:
        return f.read()

def yaz(y, s):
    with open(y, "w", encoding="utf-8") as f:
        f.write(s)

for y in ("app/data/hayrat_tek.tsv", "tools/hayrat_tek_karar.tsv", "app/data/duzeltmeler.tsv", "tests/test_tur_m.py"):
    if not os.path.exists(y):
        print("HATA: bulunamadi:", y, "(once tur_m_yama.py uygulanmali)")
        sys.exit(1)

KARAR = "tools/hayrat_tek_karar.tsv"
metin = "# Tur M: hayrat_tek_supheli.tsv'deki kelimelerin karari. latince<TAB>karar<TAB>yazim<TAB>hayrat_yazimi\n"
metin += "# H: Hayrat yazimi alinir; D: Hayrat yanlis, dogru yazim; A: alinmaz (cevirici dogru, es sesli ya da Hayrat'in azinlik yazimi: Tur M2). hayrat_tek_uret.py bunu okur.\n"
metin += "".join("\t".join(r[:4]) + "\n" for r in VERI)
if oku(KARAR) == metin:
    print("ATLANDI: karar dosyasi zaten guncel")
else:
    yaz(KARAR, metin)
    print("TAMAM: karar dosyasi guncellendi:", sum(1 for r in VERI if r[1] == "A"), "A,", sum(1 for r in VERI if r[1] == "H"), "H,", sum(1 for r in VERI if r[1] == "D"), "D")

# hayrat_tek.tsv: karar listesindeki anahtarlar silinip H/D yeniden yazilir; Tur L kaydi durumundayim \u062f\u0648\u0631\u0648\u0645 ile
anahtar = {unicodedata.normalize("NFC", r[0]) for r in VERI}
s = oku("app/data/hayrat_tek.tsv").split("\n")
bas = [x for x in s if x.startswith("#")]
govde = []
for x in s:
    if not x or x.startswith("#"):
        continue
    if unicodedata.normalize("NFC", x.split("\t")[0]) in anahtar:
        continue
    govde.append(x)
govde += [f"{k}\t{yz}\t{'hayrat' if c == 'H' else 'denetim'}\t{n}" for k, c, yz, o, n in VERI if c in ("H", "D")]
govde = sorted(govde)
govde = [("durumunday\u0131m\t\u062f\u0648\u0631\u0648\u0645\u0646\u062f\u0647\u200c\u06cc\u0645\tdenetim\t1" if x.startswith("durumunday\u0131m\t") else x) for x in govde]
yeni = "\n".join(bas + govde) + "\n"
if oku("app/data/hayrat_tek.tsv") == yeni:
    print("ATLANDI: hayrat_tek.tsv zaten guncel")
else:
    yaz("app/data/hayrat_tek.tsv", yeni)
    print("TAMAM: hayrat_tek.tsv yeniden yazildi | toplam kayit:", len(govde))

